<template><div class="space-y-6"><CPageHeader title="Presentación e integraciones" description="Personaliza el template y define las reglas de atención del hotel." /><p v-if="error" class="operation-error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p><CCard v-if="presentation"><form v-if="auth.isAdmin" class="space-y-6" @submit.prevent="save"><h2>Presentación del hotel</h2><p>El nombre y los datos de contacto se editan en <NuxtLink to="/admin/settings" class="underline">Configuración</NuxtLink>. Puedes conservar «Mi hotel» hasta personalizar el template.</p><label class="field">Descripción<textarea v-model="presentation.hotel.description" rows="4" maxlength="3000" /></label><label class="field">Imagen principal (URL HTTPS o ruta /images/)<input v-model="presentation.hotel.cover_image" maxlength="500"></label><img v-if="presentation.hotel.cover_image" :src="presentation.hotel.cover_image" alt="Vista previa de la imagen del hotel" class="property-preview"><h2>Reglas de reservas y pagos</h2><div class="operation-form"><label>Anticipación para solicitudes (horas)<input v-model.number="presentation.hotel.request_notice_hours" type="number" min="0" max="720" required></label><label>Anticipo (%)<input v-model.number="presentation.hotel.deposit_percent" type="number" min="1" max="100" required></label><label>Vencimiento del enlace de pago (horas)<input v-model.number="presentation.hotel.payment_due_hours" type="number" min="1" max="168" required></label></div><h2>Habitaciones</h2><section v-for="r in presentation.rooms" :key="r.id" class="space-y-3"><h3>{{ r.name }}</h3><label class="field">Descripción<textarea v-model="r.description" rows="3" maxlength="3000" /></label><label class="field">Foto (URL HTTPS o ruta /images/)<input v-model="r.image_url" maxlength="500"></label><img v-if="r.image_url" :src="r.image_url" :alt="`Vista previa de ${r.name}`" class="property-preview" loading="lazy"></section><CButton type="submit" :loading="busy">Guardar presentación y reglas</CButton></form></CCard><CCard v-if="mail" class="space-y-4"><h2>Entrega de correos</h2><p>{{ mail.configured?'SMTP configurado':'SMTP pendiente de configurar' }} · {{ mail.demo?'Buzón local de demostración':'Entrega al proveedor configurado' }}</p><p v-if="mail.demo">Los mensajes de la demo se consultan en <a href="http://localhost:8025" target="_blank" rel="noopener noreferrer" class="underline">el buzón local</a>; no salen a Internet.</p><CButton variant="secondary" :loading="busy" @click="loadMail">Actualizar estado</CButton><div class="operation-scroll"><table class="operation-table"><thead><tr><th>Destinatario</th><th>Asunto</th><th>Estado</th><th>Acción</th></tr></thead><tbody><tr v-for="m in mail.messages" :key="m.id"><td>{{ m.recipient }}</td><td>{{ m.subject }}</td><td>{{ m.sent_at?'Entregado a SMTP':m.last_error||'En cola' }}</td><td><CButton v-if="!m.sent_at" variant="secondary" size="sm" :disabled="busy" @click="retryMail(m.id)">Reintentar</CButton></td></tr></tbody></table></div></CCard><CCard v-if="auth.isAdmin" class="space-y-3"><h2>Respaldos de PostgreSQL</h2><template v-if="backup?.latest"><p>Última copia: {{ backup.latest.archive }}</p><p>{{ backup.latest.restored?'Restauración de prueba completada':'Pendiente de verificar' }}</p></template><p v-else>Todavía no hay una copia verificada. Revisa el servicio backups.</p><p>{{ backup?.latest?.offsite_verified ? 'La última copia también se verificó en el destino externo.' : 'Falta una copia externa verificada. Configura el destino antes de producción.' }}</p><p v-if="backup?.status?.ok===false" role="alert" class="operation-error">El último intento falló. Se conservan las copias anteriores; revisa los logs del servicio backups.</p></CCard></div></template>
<script setup lang="ts">
import {useApiClient} from '~/services/api'
import type {BackupStatus} from '~/types/generated/api'
import type {Presentation,MailStatus} from '~/types/guestServices'
definePageMeta({middleware:['auth','receptionist']})
const api=useApiClient(),{get,post,run,error,busy}=useOperations(),auth=useAuthStore(),presentation=ref<Presentation>(),mail=ref<MailStatus>(),message=ref(''),backup=ref<BackupStatus>()
const fetchMail=async()=>{if(auth.isAdmin)mail.value=(await get<MailStatus>('email-status')).data}
const loadMail=()=>run(fetchMail)
const save=()=>run(async()=>{if(!presentation.value)return;await api.request('/operations/presentation',{method:'PUT',body:{...presentation.value.hotel,rooms:presentation.value.rooms.map(r=>({id:r.id,description:r.description,image_url:r.image_url}))},retry:0});message.value='Presentación y reglas guardadas.'})
const retryMail=(id:number)=>run(async()=>{await post(`email-status/${id}/retry`,{});await fetchMail()})
onMounted(()=>run(async()=>{presentation.value=(await get<Presentation>('presentation')).data;await fetchMail();if(auth.isAdmin)backup.value=(await get<BackupStatus>('backup-status')).data}))
</script>
<style scoped>.field{display:flex;flex-direction:column;gap:8px;font-size:13px}.field input,.field textarea{padding:12px;border:1px solid var(--border-color);border-radius:8px;color:var(--text-primary);background:var(--bg-secondary);width:100%}.property-preview{width:100%;max-width:480px;height:220px;object-fit:cover;border-radius:12px}h3{font-weight:500}</style>
